rules:
  - id: no-hardcoded-secrets-typescript
    languages: [typescript]
    severity: ERROR
    message: Secret or credential is hardcoded in source; load it from an environment variable or secret manager instead.
    metadata:
      category: security
    pattern-either:
      - pattern-regex: 'AKIA[0-9A-Z]{16}'
      - pattern-regex: 'gh[pousr]_[A-Za-z0-9]{36}'
      - pattern-regex: 'xox[baprs]-[A-Za-z0-9-]{10,}'
      - pattern-regex: '-----BEGIN [A-Z ]*PRIVATE KEY-----'
      - pattern-regex: '[a-zA-Z][a-zA-Z0-9+.-]*://[^\s:/@''"]+:[^\s@''"]+@'
      - pattern-regex: '(?i)password=[^;\s''"]+'
```

